        __uint128_t mid_lo = mid << 64;
        __uint128_t lo = p00 + mid_lo;
        __uint128_t c2 = (lo < p00) ? 1 : 0;
        __uint128_t hi = p11 + (mid >> 64) + (c1 << 64) + c2;
